import numpy as np
def equation(eps, T, params):
    a,b,c,d,e_,f,g,h,i,j,k2,l2 = list(params[:10])+[0.0,0.0]
    num = a + b/T + (c + d/T + f*np.sqrt(T))*eps + g*eps**2
    den = 1 + e_*eps + h*eps**2 + (j/T)*eps*eps
